// Branded types prevent mixing up IDs
interface UserId {
  readonly brand: 'UserId';
  readonly value: string;
}

interface ProductId {
  readonly brand: 'ProductId';
  readonly value: string;
}

function createUserId(value: string): UserId {
  return { brand: 'UserId', value };
}

function createProductId(value: string): ProductId {
  return { brand: 'ProductId', value };
